<section class="panel instance-panel" id="instances" aria-labelledby="instances-title">
    <h2 id="instances-title">Instâncias GOWA e webhooks</h2>
    <p>O cadastro fica desabilitado por padrão. Marque a opção para habilitá-lo nesta instância. Provisionamento e rotação revelam a URL do webhook uma única vez; a rotação invalida imediatamente a URL anterior.</p>
    <?php if (!$gowaStatus['configured']): ?><p class="locked-notice">Configure a conexão global antes de provisionar instâncias.</p><?php endif; ?>
    <?php if (!$publicBaseReady): ?><p class="locked-notice">Configure APP_BASE_URL com o endereço HTTPS público da instalação antes de provisionar instâncias.</p><?php endif; ?>
    <form method="post" class="provision-form">
        <input type="hidden" name="csrf_token" value="<?= atendimentoIaEscape($csrfToken) ?>"><input type="hidden" name="action" value="provision_instance">
        <label>Cliente<select name="tenant_id" required><option value="">Selecione o cliente</option><?php foreach ($tenants as $tenant): ?><option value="<?= (int) $tenant['id'] ?>"><?= atendimentoIaEscape((string) $tenant['nome']) ?></option><?php endforeach; ?></select></label>
        <label>Escopo<select name="subclient_id"><option value="">Instância da sede</option><?php foreach ($units as $unit): ?><option value="<?= (int) $unit['id'] ?>"><?= atendimentoIaEscape((string) $unit['nome']) ?> · unidade <?= (int) $unit['parent_id'] ?></option><?php endforeach; ?></select></label>
        <label class="flow-optin"><input type="checkbox" name="flow_enabled" value="1"> Habilitar cadastro e emissão neste fluxo</label>
        <button class="primary-button" type="submit" <?= (!$gowaStatus['configured'] || !$publicBaseReady) ? 'disabled' : '' ?>>Provisionar instância</button>
    </form>
    <?php if ($instances === []): ?><p class="empty-state">Nenhuma instância GOWA provisionada.</p><?php else: ?><div class="instance-list">
        <?php foreach ($instances as $instance): ?><article class="instance-card"><div><h3><?= atendimentoIaEscape((string) $instance['nome_instancia']) ?></h3><p><?= atendimentoIaEscape((string) ($instance['tenant_nome'] ?? 'Cliente indisponível')) ?><?= $instance['unidade_nome'] ? ' · ' . atendimentoIaEscape((string) $instance['unidade_nome']) : ' · sede' ?></p></div>
            <dl><div><dt>Estado registrado</dt><dd><?= atendimentoIaEscape((string) $instance['estado']) ?></dd></div><div><dt>Webhook</dt><dd><?= $instance['estado'] === 'ativa' ? 'URL protegida; sem segredo exibido' : 'Sem webhook ativo' ?></dd></div><div><dt>Cadastro</dt><dd><?= (int) ($instance['fluxo_cadastro_ativo'] ?? 0) === 1 ? 'Habilitado' : 'Desabilitado' ?></dd></div><div><dt>Atualizada</dt><dd><?= atendimentoIaEscape((string) $instance['atualizado_em']) ?></dd></div></dl>
            <?php if ($instance['estado'] === 'ativa'): ?><div class="instance-actions"><form method="post"><input type="hidden" name="csrf_token" value="<?= atendimentoIaEscape($csrfToken) ?>"><input type="hidden" name="action" value="rotate_webhook"><input type="hidden" name="instance_id" value="<?= (int) $instance['id'] ?>"><button class="secondary-button" type="submit">Rotacionar webhook</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?= atendimentoIaEscape($csrfToken) ?>"><input type="hidden" name="action" value="toggle_flow"><input type="hidden" name="instance_id" value="<?= (int) $instance['id'] ?>"><input type="hidden" name="enabled" value="<?= (int) ($instance['fluxo_cadastro_ativo'] ?? 0) === 1 ? '0' : '1' ?>"><button class="secondary-button" type="submit"><?= (int) ($instance['fluxo_cadastro_ativo'] ?? 0) === 1 ? 'Desabilitar cadastro' : 'Habilitar cadastro' ?></button></form></div><?php endif; ?>
        </article><?php endforeach; ?></div><?php endif; ?>
</section>
